-- pup-misc / smokes | install.sql
--
-- Creates:  smokes (one row per usable pipe, cigar, cigarette or chew item and what it does)
-- Seeds:    the stock smokes list (67 rows). It is reference data the vorp_admin smokes panel edits,
--           not player data. The code only seeds the table from config/smokes/smokes.lua, which is
--           empty, so without these rows no smoke is usable. INSERT IGNORE leaves your own tuning alone.
-- Items:    every smoke item plus pipe (the pipe smokes need one in the satchel).
-- Requires: VORP core items.
--
-- server/smokes/main.lua also creates smokes on start.
-- Safe to run more than once.

CREATE TABLE IF NOT EXISTS `smokes` (
  `name` varchar(64) NOT NULL,
  `pipe` tinyint(1) NOT NULL DEFAULT 0,
  `subitem` tinyint(1) NOT NULL DEFAULT 1,
  `typeof` varchar(16) NOT NULL DEFAULT 'cigar',
  `high` tinyint(1) NOT NULL DEFAULT 0,
  `hightype` varchar(64) NOT NULL DEFAULT '',
  `highduration` int(11) NOT NULL DEFAULT 0,
  `boost` tinyint(1) NOT NULL DEFAULT 0,
  `healthboost` float NOT NULL DEFAULT 0,
  `staminaboost` float NOT NULL DEFAULT 0,
  `drunkamount` float NOT NULL DEFAULT 0,
  `drunkscreen` float NOT NULL DEFAULT 0,
  `drunkwalk` float NOT NULL DEFAULT 0,
  `turbo` tinyint(1) NOT NULL DEFAULT 0,
  `effectinterval` int(11) NOT NULL DEFAULT 10,
  `effects` longtext DEFAULT NULL,
  PRIMARY KEY (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


